fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    let rows = y.len();
    let cols = x.len();
    
    // Create first matrix (X values repeated across rows)
    let mut x_grid = Vec::with_capacity(rows);
    for _ in 0..rows {
        let row = x.clone();  // Each row is a copy of the x array
        x_grid.push(row);
    }
    
    // Create second matrix (Y values repeated across columns)
    let mut y_grid = Vec::with_capacity(rows);
    for i in 0..rows {
        let mut row = Vec::with_capacity(cols);
        for _ in 0..cols {
            row.push(y[i]);  // Each column in this row gets the same y value
        }
        y_grid.push(row);
    }
    
    (x_grid, y_grid)
}